{
  "table": {
    "name": "Magic: The Gathering set catalogue",
    "purpose": "One row per Magic: The Gathering set/release (expansion, core set, promo series, deck product, memorabilia, etc.) - 551 sets spanning 1993-08-05 (Limited Edition Alpha, the first Magic set) to 2021-03-19. This is the MTGJSON set structure: the cards table references a set via cards.setCode, and set_translations holds localized set names. Columns carry the set's identity (code, name), sizing, release metadata, booster composition, and IDs for external vendors (Cardmarket, TCGplayer, Magic Online)."
  },
  "columns": {
    "baseSetSize": {
      "role": "numeric",
      "name": "Base set size",
      "description": "Number of distinct cards in the set as released, excluding alternate printings/variants. Ranges 0-1694 (median 26); small values (1-6) are typical of promo sets, large ones of expansions/core sets. Always <= totalSetSize, and equal to it for sets without extra printings.",
      "status": "resolved"
    },
    "block": {
      "role": "category",
      "name": "Block / product line",
      "description": "The Magic block or product family the set belongs to: true blocks ('Theros', 'Kamigawa', 'Scars of Mirrodin', 'Shadows over Innistrad') as well as series groupings for non-block products ('Core Set', 'Commander', 'Judge Gift Cards', 'Friday Night Magic', 'Magic Player Rewards'). Null for the ~51% of sets (mostly one-off promos/memorabilia) that belong to no block.",
      "status": "resolved"
    },
    "booster": {
      "role": "free_text",
      "name": "Booster pack configuration",
      "description": "Serialized JSON (stored as text) describing how the set's booster packs are composed: per-variant ('default', 'arena') lists of boosters with slot contents such as basic, common, uncommon, rare, rareMythic, land and special slots (e.g., double-faced card slots). The most common value is the standard 15-card draft booster (1 basic, 10 common, 3 uncommon, 1 rare/mythic). Null for the ~75% of sets sold without boosters (promos, duel decks, memorabilia).",
      "status": "resolved"
    },
    "code": {
      "role": "code",
      "name": "Set code",
      "description": "Unique short code identifying the set (e.g., TSP = Time Spiral, 10E = Tenth Edition, PGRN = Guilds of Ravnica promos, PWP09 = Wizards Play Network 2009 promos). Natural key of the table: referenced by cards.setCode and set_translations.setCode.",
      "status": "resolved"
    },
    "id": {
      "role": "numeric",
      "name": "Set ID (surrogate key)",
      "description": "Auto-increment surrogate primary key, sequential 1-551 with one value per set; carries no external meaning.",
      "status": "resolved"
    },
    "isFoilOnly": {
      "role": "boolean",
      "name": "Foil-only flag",
      "description": "Boolean (0/1): 1 when every card in the set exists only in foil (167 sets, mostly promos and premium products); 0 otherwise.",
      "status": "resolved"
    },
    "isForeignOnly": {
      "role": "boolean",
      "name": "Foreign-only flag",
      "description": "Boolean (0/1): 1 when the set was printed only in non-English languages (16 sets); 0 otherwise.",
      "status": "resolved"
    },
    "isNonFoilOnly": {
      "role": "boolean",
      "name": "Non-foil-only flag",
      "description": "Boolean (0/1): 1 when the set's cards exist only in non-foil (106 sets); 0 otherwise. Counterpart of isFoilOnly.",
      "status": "resolved"
    },
    "isOnlineOnly": {
      "role": "boolean",
      "name": "Online-only flag",
      "description": "Boolean (0/1): 1 when the set exists only in digital form (Magic Online / MTG Arena), 26 sets; 0 otherwise.",
      "status": "resolved"
    },
    "isPartialPreview": {
      "role": "boolean",
      "name": "Partial preview flag",
      "description": "Boolean (0/1): 1 when the set was only partially previewed/spoiled, i.e., its full card list was not yet known when the data was captured (exactly 1 set, presumably the most recent release); 0 otherwise.",
      "status": "resolved"
    },
    "keyruneCode": {
      "role": "code",
      "name": "Keyrune set-symbol code",
      "description": "Code for the Keyrune icon font used to render the set's symbol/logo. Equals the set's own code for sets with a unique symbol (TSP, ALL, M14, ARC); promo and miscellaneous sets share generic icons (PMEI, DCI, DEFAULT, PARL, PMPS), which is why only 249 distinct values exist for 551 sets.",
      "status": "resolved"
    },
    "mcmId": {
      "role": "numeric",
      "name": "Cardmarket set ID",
      "description": "Magic Card Market (Cardmarket) expansion ID for the set; unique among non-null values, null for the ~64% of sets Cardmarket does not catalogue (promos, memorabilia).",
      "status": "resolved"
    },
    "mcmIdExtras": {
      "role": "numeric",
      "name": "Cardmarket extras-set ID",
      "description": "Cardmarket ID of the set's separate 'Extras' entry, used when Cardmarket splits a set's supplementary cards into their own expansion; populated for only 10 sets, with values in the same ID range as mcmId.",
      "status": "resolved"
    },
    "mcmName": {
      "role": "free_text",
      "name": "Cardmarket set name",
      "description": "The set's name as listed on Magic Card Market (e.g., 'Aether Revolt', 'Zendikar Expeditions', 'Portal Second Age'); unique, null exactly where mcmId is null.",
      "status": "resolved"
    },
    "mtgoCode": {
      "role": "code",
      "name": "Magic Online set code",
      "description": "The set's code as used in Magic Online, which can differ from the main set code (e.g., V10, PR, DRB); null for the ~71% of sets not available on MTGO.",
      "status": "resolved"
    },
    "name": {
      "role": "free_text",
      "name": "Set name",
      "description": "Full human-readable name of the set (e.g., 'Ultimate Masters', 'Magic 2010', 'Mirrodin Promos', 'World Championship Decks 2000'); unique across all 551 rows.",
      "status": "resolved"
    },
    "parentCode": {
      "role": "code",
      "name": "Parent set code",
      "description": "Set code of the parent release this set belongs to (e.g., several promo/token sets point at ZNR = Zendikar Rising, BFZ = Battle for Zendikar, BNG/FRF/JOU = Theros-block expansions); null for standalone sets (~72%).",
      "status": "resolved"
    },
    "releaseDate": {
      "role": "date",
      "name": "Release date",
      "description": "The set's release date in ISO YYYY-MM-DD format (stored as text). Spans 1993-08-05 (Limited Edition Alpha, the first Magic set) to 2021-03-19, the snapshot's most recent release; many promo sets carry a nominal January 1 or December 1 date.",
      "status": "resolved"
    },
    "tcgplayerGroupId": {
      "role": "numeric",
      "name": "TCGplayer group ID",
      "description": "TCGplayer product-group ID for the set (TCGplayer groups products by set); null for ~53% of sets. The most frequent value, 62, is shared by 21 sets, so some IDs are catch-all groups covering several sets rather than one per set.",
      "status": "resolved"
    },
    "totalSetSize": {
      "role": "numeric",
      "name": "Total set size",
      "description": "Total number of cards in the set counting every printing/variant; always >= baseSetSize (mean 102.6 vs 99.6) and equal to it for sets without alternate printings. Ranges 0-1694, median 26.",
      "status": "resolved"
    },
    "type": {
      "role": "category",
      "name": "Set type",
      "description": "Category of the release: promo (234 sets), expansion (87), memorabilia (34), box (27), duel_deck (27), plus rarer kinds such as premium_deck, draft_innovation, archenemy, spellbook (20 distinct types in total).",
      "status": "resolved"
    }
  }
}
